import { OpenRouter } from '@openrouter/sdk';
if (!process.env.VOLTER_WORLD) throw new Error('Run this app through its World.');
const openRouter = new OpenRouter({ apiKey: process.env.OPENROUTER_API_KEY ?? '' });
const result = await openRouter.chat.send({ chatRequest: { model: 'z-ai/glm-5.2', messages: [{ role: 'user', content: 'Say hello to Ada in one sentence.' }] } });
const text = result.choices?.[0]?.message?.content;
if (typeof text !== 'string' || !text) throw new Error('The completion carried no text: ' + JSON.stringify(result).slice(0, 300));
if (result.model !== 'z-ai/glm-5.2') throw new Error('The completion names another model: ' + String(result.model));
console.log(JSON.stringify({ model: result.model, text }));
